import { isLanguage } from '@shared/langUtils.js';
import { useEffect, useState } from 'react';
import { categoryKeys, getOsmMapping } from './osmNameResolver.js';
import type { Node } from './types.js';

/** Readable OSM key and value labels, generated by `pnpm gen-osm-tag-labels`. */
export type OsmTagLabels = {
  keys: Record<string, string>;
  values: Record<string, Record<string, string>>;
  /** Keys whose values come from a fixed list rather than free text. */
  enums: Set<string>;
  /** Our own kind names, which win over iD's for type values. */
  nameMapping: Node;
  /** iD's ISC notice; read so the bundler can't drop it from the chunk. */
  license: string;
};

// Read synchronously on mount, so an object selected later never paints raw.
const loaded = new Map<string, OsmTagLabels>();

const loading = new Map<string, Promise<OsmTagLabels>>();

function loadOsmTagLabels(language: string): Promise<OsmTagLabels> {
  const lang = isLanguage(language) ? language : 'en';

  let promise = loading.get(lang);

  if (!promise) {
    promise = Promise.all([
      import(
        /* webpackChunkName: "osm-tag-labels-[request]" */
        `./tagLabels/${lang}.json`
      ),
      getOsmMapping(lang),
    ]).then(([{ default: data }, { osmTagToNameMapping }]) => {
      const labels: OsmTagLabels = {
        keys: data.keys,
        values: data.values,
        enums: new Set(data.enums),
        nameMapping: osmTagToNameMapping,
        license: data.license,
      };

      loaded.set(lang, labels);

      return labels;
    });

    // A failed chunk is retried by the next mount.
    promise.catch(() => loading.delete(lang));

    loading.set(lang, promise);
  }

  return promise;
}

/** The labels for `language` once loaded, while `enabled`; raw tags until then. */
export function useOsmTagLabels(
  language: string,
  enabled: boolean,
): OsmTagLabels | undefined {
  const lang = isLanguage(language) ? language : 'en';

  // In state rather than read from `loaded` at render, which the React
  // Compiler would memoize.
  const [state, setState] = useState(() => {
    const labels = loaded.get(lang);

    return labels && { lang, labels };
  });

  const stateLang = state?.lang;

  useEffect(() => {
    if (!enabled || stateLang === lang) {
      return;
    }

    let current = true;

    loadOsmTagLabels(lang).then(
      (labels) => {
        if (current) {
          setState({ lang, labels });
        }
      },
      () => {
        // Offline or a stale chunk: the tags stay raw.
      },
    );

    return () => {
      current = false;
    };
  }, [lang, enabled, stateLang]);

  return enabled && state?.lang === lang ? state.labels : undefined;
}

// `name:de`, `alt_name:en-GB`.
const LOCALIZED_NAME_RE = /^((?:\w+_)?name):([a-z]{2,3}(?:-[A-Za-z0-9]+)*)$/;

const displayNames = new Map<string, Intl.DisplayNames>();

function languageName(language: string, code: string): string | undefined {
  let names = displayNames.get(language);

  if (!names) {
    names = new Intl.DisplayNames(language, {
      type: 'language',
      fallback: 'none',
    });

    displayNames.set(language, names);
  }

  try {
    return names.of(code);
  } catch {
    // Not a well-formed language tag.
    return undefined;
  }
}

/** `obj[key]` if it is its own string, never an inherited `constructor`. */
function own(obj: object | undefined, key: string): string | undefined {
  const value = obj && Object.hasOwn(obj, key) ? (obj as Node)[key] : undefined;

  return typeof value === 'string' ? value : undefined;
}

export function osmTagKeyLabel(
  labels: OsmTagLabels,
  key: string,
  language: string,
): string | undefined {
  const label = own(labels.keys, key);

  if (label) {
    return label;
  }

  const m = LOCALIZED_NAME_RE.exec(key);

  const base = m && own(labels.keys, m[1]);

  const lang = base && languageName(language, m[2]);

  return lang ? `${base} (${lang})` : undefined;
}

export function osmTagValueLabel(
  labels: OsmTagLabels,
  yesNo: { yes: string; no: string } | undefined,
  key: string,
  value: string,
): string | undefined {
  // Our own kind names come first: they are what the object's name says.
  const mapped = categoryKeys.has(key) ? labels.nameMapping[key] : undefined;

  const ownName =
    typeof mapped === 'object' && Object.hasOwn(labels.nameMapping, key)
      ? own(mapped, value)
      : undefined;

  if (ownName && !ownName.includes('{')) {
    return ownName;
  }

  const values = Object.hasOwn(labels.values, key)
    ? labels.values[key]
    : undefined;

  if (own(values, value)) {
    return own(values, value);
  }

  // Not for free text: `ref=no` is a literal.
  return !labels.enums.has(key)
    ? undefined
    : value === 'yes'
      ? yesNo?.yes
      : value === 'no'
        ? yesNo?.no
        : undefined;
}
